components.css:
.ds-database-panel{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,"Noto Sans","Liberation Sans",sans-serif,"Apple Color Emoji","Segoe UI Emoji","Segoe UI Symbol","Noto Color Emoji";height:620px;max-width:100%;}.ds-database-panel button,.ds-database-panel input,.ds-database-panel textarea,.ds-database-panel select{font-family:inherit;line-height:1.5;}.ds-database-panel button{cursor:pointer;}.ds-database-panel button:focus-visible,.ds-database-panel input:focus-visible,.ds-database-panel summary:focus-visible,.ds-database-panel textarea:focus-visible,.ds-database-panel select:focus-visible{outline:2px solid #007bff;outline-offset:1px;}.ds-form-control,.ds-custom-select{display:block;width:100%;padding:.25rem .5rem;font-size:.875rem;font-weight:400;line-height:1.5;color:#495057;background-color:#fff;border:1px solid #ced4da;border-radius:.2rem}.ds-custom-select{height:31px}.ds-form-control:focus,.ds-custom-select:focus{outline:0;border-color:#80bdff;box-shadow:0 0 0 .2rem rgba(0,123,255,.25)}.ds-btn{display:inline-block;padding:.25rem .5rem;font-size:.875rem;color:#007bff;background:transparent;border:1px solid #007bff;border-radius:.2rem}.ds-btn:hover,.ds-btn:active{color:#fff;background:#007bff}.ds-btn:focus-visible{box-shadow:0 0 0 .2rem rgba(0,123,255,.5)}.ds-btn:disabled{opacity:.65;cursor:default}.ds-database-panel {
  width: 380px;
  flex: 0 0 380px;
  min-height: 0;
  display: flex;
  flex-direction: column;
  border-left: 1px solid #ced4da;
  background: #fff;
  font-size: 14px;
  line-height: 1.5;
  overflow: auto;
}
.ds-data-heading {
  height: 47px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 14px;
  border-bottom: 1px solid #e9ecef;
  font-weight: 600;
}
.ds-data-count {
  color: #6c757d;
  font-size: 12px;
  font-weight: 400;
  font-variant-numeric: tabular-nums;
}
.ds-database-source {
  padding: 14px 14px 0;
  flex-shrink: 0;
}
.ds-database-load-row {
  display: flex;
  align-items: center;
  gap: 8px;
}
.ds-database-load-row button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}
.ds-database-load-row select {
  width: 82px;
  margin-left: auto;
}
.ds-database-file-status {
  margin-top: 8px;
  color: #6c757d;
  font-size: 12px;
}
.ds-database-file-status span {
  display: block;
}
.ds-database-filename {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #495057;
}
.ds-population-picker {
  padding: 18px 14px 0;
  flex-shrink: 0;
}
.ds-picker-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 6px;
}
.ds-picker-heading label {
  font-weight: 600;
  margin: 0;
}
.ds-data-text-action {
  border: 0;
  padding: 0;
  background: transparent;
  color: #007bff;
  font-size: 12px;
  white-space: nowrap;
}
.ds-data-text-action:hover {
  text-decoration: underline;
}
.ds-population-token-box {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  align-content: flex-start;
  gap: 4px;
  padding: 7px;
  min-height: 86px;
  max-height: 210px;
  overflow: auto;
  border: 1px solid #ced4da;
  border-radius: 3px;
  cursor: text;
}
.ds-population-token-box:focus-within {
  border-color: #80bdff;
  box-shadow: 0 0 0 2px #cce5ff;
}
.ds-population-token-box input {
  border: 0;
  background: transparent;
  padding: 3px 2px;
  flex: 1 1 180px;
  width: 100%;
  min-width: 0;
  font-size: 13px;
  outline: none;
}
.ds-population-token-box input:focus-visible {
  outline: none;
}
.ds-population-token-box input::placeholder {
  color: #6c757d;
  opacity: 1;
}
.ds-population-chip {
  display: inline-flex;
  align-items: center;
  max-width: 100%;
  gap: 5px;
  padding: 2px 4px 2px 6px;
  border: 1px solid #a9caff;
  background: #e4efff;
  color: #0056b3;
  border-radius: 3px;
  font-size: 12px;
}
.ds-population-chip.ds-individual {
  background: #f2eafa;
  color: #653b83;
  border-color: #d0b5e4;
}
.ds-population-chip-text {
  overflow-wrap: anywhere;
  min-width: 0;
}
.ds-chip-count {
  font-size: 10px;
  font-variant-numeric: tabular-nums;
  opacity: 0.85;
}
.ds-population-chip button {
  display: inline-flex;
  align-items: center;
  border: 0;
  padding: 1px;
  background: transparent;
  color: inherit;
  flex-shrink: 0;
}
.ds-population-chip button:hover {
  background: #cce5ff;
}
.ds-picker-hint {
  margin: 6px 0 0;
  font-size: 12px;
  color: #6c757d;
}
.ds-database-results {
  margin: 10px 14px 0;
  min-height: 60px;
  flex: 1 1 180px;
  overflow: auto;
  border-top: 1px solid #e9ecef;
}
.ds-database-results:empty {
  border-top-color: transparent;
}
.ds-result-heading {
  display: flex;
  justify-content: space-between;
  padding: 7px 4px;
  font-size: 12px;
  font-weight: 600;
  color: #495057;
  background: #f8f9fa;
}
.ds-result-heading span {
  color: #6c757d;
  font-weight: 400;
}
.ds-database-group-row {
  display: flex;
  align-items: stretch;
  border-bottom: 1px solid #e9ecef;
}
.ds-group-expand {
  width: 25px;
  flex: 0 0 25px;
  border: 0;
  background: transparent;
  padding: 6px 0;
  color: #6c757d;
}
.ds-group-select {
  display: flex;
  align-items: center;
  gap: 7px;
  justify-content: space-between;
  width: 100%;
  min-width: 0;
  border: 0;
  padding: 8px 4px;
  text-align: left;
  background: transparent;
  color: #212529;
  font-size: 13px;
}
.ds-group-select > span:first-child {
  overflow-wrap: anywhere;
  min-width: 0;
}
.ds-group-select small {
  display: block;
  color: #6c757d;
  font-size: 11px;
}
.ds-group-sample-count {
  color: #6c757d;
  font-size: 11px;
  white-space: nowrap;
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}
.ds-group-select[aria-pressed="true"] {
  color: #0056b3;
  background: #e4efff;
}
.ds-group-select:hover,
.ds-group-expand:hover,
.ds-database-sample:hover {
  background: #f1f6fd;
}
.ds-database-sample {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 7px;
  border: 0;
  border-bottom: 1px solid #e9ecef;
  background: transparent;
  text-align: left;
  padding: 7px 5px;
  color: #212529;
  font-size: 13px;
}
.ds-database-sample.ds-nested {
  padding-left: 26px;
  font-size: 12px;
}
.ds-database-sample[aria-pressed="true"] {
  background: #f2eafa;
  color: #653b83;
}
.ds-choice-check {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  border: 1px solid #adb5bd;
  border-radius: 2px;
}
.ds-sample-copy {
  min-width: 0;
  overflow-wrap: anywhere;
}
.ds-sample-copy small {
  display: block;
  font-size: 11px;
  color: #6c757d;
}
.ds-result-empty,
.ds-result-limit {
  padding: 10px 4px;
  font-size: 12px;
  color: #6c757d;
  overflow-wrap: anywhere;
}
.ds-more-samples {
  margin: 7px 0 7px 26px;
}
.ds-manual-source {
  flex-shrink: 0;
  padding: 10px 14px 12px;
  border-top: 1px solid #e9ecef;
}
.ds-manual-source summary {
  font-weight: 600;
  font-size: 13px;
  cursor: pointer;
}
.ds-manual-entry {
  padding-top: 8px;
}
.ds-manual-entry textarea {
  resize: vertical;
  min-height: 76px;
  max-height: 180px;
  font-size: 12px;
}
.ds-manual-entry textarea:focus-visible {
  outline-offset: 0;
}
.ds-manual-actions {
  display: flex;
  gap: 8px;
  justify-content: space-between;
  margin-top: 8px;
}
.ds-manual-actions select {
  width: 86px;
}
.ds-data-error {
  padding: 7px 8px;
  margin: 8px 0 0;
  color: #842029;
  background: #fff5f5;
  border: 1px solid #f1c2c7;
  font-size: 12px;
  overflow-wrap: anywhere;
}
.ds-selection-status {
  padding: 8px 14px;
  flex-shrink: 0;
  border-top: 1px solid #e9ecef;
  color: #495057;
  font-size: 12px;
}
